from scipy.optimize import least_squares
def fit(f,p0,n=10):
    best=None
    for s in range(n):
        p=np.random.default_rng(s).normal(size=len(p0))*(0.5 if s else 0)+np.array(p0,dtype=float)
        try:
            r=least_squares(lambda q: f(q)-sigma,p,max_nfev=2000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return round(best.cost*2/len(sigma)/np.var(sigma),7), np.round(best.x,4)
